import re

_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration(text: str) -> int:
    s = text.strip()
    if not s or not re.fullmatch(r"(?:\d+\s*[dhms]\s*)+", s):
        raise ValueError(f"invalid duration: {text!r}")
    seen = set()
    total = 0
    for n, unit in re.findall(r"(\d+)\s*([dhms])", s):
        if unit in seen:
            raise ValueError(f"repeated unit {unit!r} in {text!r}")
        seen.add(unit)
        total += int(n) * _UNITS[unit]
    return total
